CREATE TABLE "User" ("id" TEXT NOT NULL PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"currency" TEXT NOT NULL DEFAULT 'IQD',"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL);
CREATE TABLE "Category" ("id" TEXT NOT NULL PRIMARY KEY,"name" TEXT NOT NULL,"icon" TEXT,"isSystem" BOOLEAN NOT NULL DEFAULT false,"userId" TEXT,FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Transaction" ("id" TEXT NOT NULL PRIMARY KEY,"amount" INTEGER NOT NULL,"type" TEXT NOT NULL,"description" TEXT NOT NULL,"source" TEXT NOT NULL DEFAULT 'app',"status" TEXT NOT NULL DEFAULT 'confirmed',"transactionDate" DATETIME NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,"userId" TEXT NOT NULL,"categoryId" TEXT,FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY ("categoryId") REFERENCES "Category" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "Income" ("id" TEXT NOT NULL PRIMARY KEY,"amount" INTEGER NOT NULL,"type" TEXT NOT NULL,"payDay" INTEGER NOT NULL,"recurring" BOOLEAN NOT NULL DEFAULT false,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,"userId" TEXT NOT NULL,FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Budget" ("id" TEXT NOT NULL PRIMARY KEY,"amount" INTEGER NOT NULL,"startDate" DATETIME NOT NULL,"endDate" DATETIME NOT NULL,"userId" TEXT NOT NULL,"categoryId" TEXT,FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY ("categoryId") REFERENCES "Category" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "SavingsGoal" ("id" TEXT NOT NULL PRIMARY KEY,"name" TEXT NOT NULL,"targetAmount" INTEGER NOT NULL,"currentAmount" INTEGER NOT NULL DEFAULT 0,"targetDate" DATETIME,"status" TEXT NOT NULL DEFAULT 'active',"userId" TEXT NOT NULL,FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "TelegramAccount" ("id" TEXT NOT NULL PRIMARY KEY,"telegramUserId" TEXT NOT NULL UNIQUE,"chatId" TEXT NOT NULL,"userId" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "TelegramLinkToken" ("id" TEXT NOT NULL PRIMARY KEY,"tokenHash" TEXT NOT NULL UNIQUE,"userId" TEXT NOT NULL,"expiresAt" DATETIME NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "TelegramUpdate" ("id" TEXT NOT NULL PRIMARY KEY,"updateId" INTEGER NOT NULL UNIQUE,"receivedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "NotificationDevice" ("id" TEXT NOT NULL PRIMARY KEY,"token" TEXT NOT NULL UNIQUE,"platform" TEXT NOT NULL,"userId" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "Transaction_userId_transactionDate_idx" ON "Transaction"("userId","transactionDate");
CREATE INDEX "Transaction_userId_status_idx" ON "Transaction"("userId","status");
